import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation that uses a bit array for space-efficient 
    membership testing. The size of the bit array and the number of hash 
    functions are determined based on the expected number of items and 
    desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.size = self._optimal_bit_array_size(expected_items, false_positive_rate)
        self.hash_count = self._optimal_hash_count(self.size, expected_items)
        self.bit_array = [0] * self.size

    def _optimal_bit_array_size(self, n: int, p: float) -> int:
        """Calculate the optimal size of the bit array."""
        return math.ceil(-n * math.log(p) / (math.log(2) ** 2))

    def _optimal_hash_count(self, m: int, n: int) -> int:
        """Calculate the optimal number of hash functions."""
        return math.ceil((m / n) * math.log(2))

    def _hashes(self, item: str) -> list:
        """Generate hash values for the provided item."""
        hash_values = []
        for i in range(self.hash_count):
            hash_digest = hashlib.md5(f"{item}{i}".encode()).hexdigest()
            hash_value = int(hash_digest, 16) % self.size
            hash_values.append(hash_value)
        return hash_values

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for hash_value in self._hashes(item):
            self.bit_array[hash_value] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is possibly in the Bloom Filter."""
        return all(self.bit_array[hash_value] for hash_value in self._hashes(item))

